   144→#[instrument(skip_all, level = "debug")]
   145→async fn fetch_and_process_blobs_v1<T: BeaconChainTypes>(
   146→    chain_adapter: FetchBlobsBeaconAdapter<T>,
   147→    block_root: Hash256,
   148→    block: Arc<SignedBeaconBlock<T::EthSpec>>,
   149→    versioned_hashes: Vec<VersionedHash>,
   150→    publish_fn: impl Fn(EngineGetBlobsOutput<T>) + Send + Sized,
   151→) -> Result<Option<AvailabilityProcessingStatus>, FetchEngineBlobError> {
   152→    let num_expected_blobs = versioned_hashes.len();
   153→    metrics::observe(&metrics::BLOBS_FROM_EL_EXPECTED, num_expected_blobs as f64);
   154→    debug!(num_expected_blobs, "Fetching blobs from the EL");
   155→    let response = chain_adapter
   156→        .get_blobs_v1(versioned_hashes)
   157→        .await
   158→        .inspect_err(|_| {
   159→            inc_counter(&metrics::BLOBS_FROM_EL_ERROR_TOTAL);
   160→        })?;
   161→
   162→    let num_fetched_blobs = response.iter().filter(|opt| opt.is_some()).count();
   163→    metrics::observe(&metrics::BLOBS_FROM_EL_RECEIVED, num_fetched_blobs as f64);
   164→
   165→    if num_fetched_blobs == 0 {
   166→        debug!(num_expected_blobs, "No blobs fetched from the EL");
   167→        inc_counter(&metrics::BLOBS_FROM_EL_MISS_TOTAL);
   168→        return Ok(None);
   169→    } else {
   170→        debug!(
   171→            num_expected_blobs,
   172→            num_fetched_blobs, "Received blobs from the EL"
   173→        );
   174→        inc_counter(&metrics::BLOBS_FROM_EL_HIT_TOTAL);
   175→    }
   176→
   177→    if chain_adapter.fork_choice_contains_block(&block_root) {
   178→        // Avoid computing sidecars if the block has already been imported.
   179→        debug!(
   180→            info = "block has already been imported",
   181→            "Ignoring EL blobs response"
   182→        );
   183→        return Ok(None);
   184→    }
   185→
   186→    let (signed_block_header, kzg_commitments_proof) = block
   187→        .signed_block_header_and_kzg_commitments_proof()
   188→        .map_err(FetchEngineBlobError::BeaconStateError)?;
   189→
   190→    let mut blob_sidecar_list = build_blob_sidecars(
   191→        &block,
   192→        response,
   193→        signed_block_header,
   194→        &kzg_commitments_proof,
   195→    )?;
   196→
   197→    if let Some(observed_blobs) =
   198→        chain_adapter.blobs_known_for_proposal(block.message().proposer_index(), block.slot())
   199→    {
   200→        blob_sidecar_list.retain(|blob| !observed_blobs.contains(&blob.blob_index()));
   201→        if blob_sidecar_list.is_empty() {
   202→            debug!(
   203→                info = "blobs have already been seen on gossip",
   204→                "Ignoring EL blobs response"
   205→            );
   206→            return Ok(None);
   207→        }
   208→    }
   209→
   210→    if let Some(known_blobs) = chain_adapter.cached_blob_indexes(&block_root) {
   211→        blob_sidecar_list.retain(|blob| !known_blobs.contains(&blob.blob_index()));
   212→        if blob_sidecar_list.is_empty() {
   213→            debug!(
   214→                info = "blobs have already been imported into data availability checker",
   215→                "Ignoring EL blobs response"
   216→            );
   217→            return Ok(None);
   218→        }
   219→    }
   220→
   221→    // Up until this point we have not observed the blobs in the gossip cache, which allows them to
   222→    // arrive independently while this function is running. In `publish_fn` we will observe them
   223→    // and then publish any blobs that had not already been observed.
   224→    publish_fn(EngineGetBlobsOutput::Blobs(blob_sidecar_list.clone()));
   225→
   226→    let availability_processing_status = chain_adapter
   227→        .process_engine_blobs(
   228→            block.slot(),
   229→            block_root,
   230→            EngineGetBlobsOutput::Blobs(blob_sidecar_list),
   231→        )
   232→        .await?;
   233→
   234→    Ok(Some(availability_processing_status))
   235→}
